import{_ as n,o as a,c as e,a2 as s}from"./chunks/framework.DnrXFDHb.js";const u=JSON.parse('{"title":"StreamMUSE","description":"实时 AI 音乐伴奏生成系统","frontmatter":{"title":"StreamMUSE","description":"实时 AI 音乐伴奏生成系统"},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1775717144000}'),r={name:"index.md"};function i(d,t,l,p,o,c){return a(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="streammuse" tabindex="-1">StreamMUSE <a class="header-anchor" href="#streammuse" aria-label="Permalink to &quot;StreamMUSE&quot;">​</a></h1><p><strong>StreamMUSE</strong> 是一个实时 AI 音乐伴奏生成系统，能够在用户演奏旋律的同时生成匹配的伴奏声部。系统支持 HTTP 推理（fake server / Lekai server）和本地 Stanley 推理两条路径。</p><hr><h2 id="核心特性" tabindex="-1">核心特性 <a class="header-anchor" href="#核心特性" aria-label="Permalink to &quot;核心特性&quot;">​</a></h2><ul><li><strong>实时生成</strong>：客户端按 tick 推进音乐时间线，在 tick=0 和每拍末尾触发下一拍推理请求</li><li><strong>多种输入方式</strong>：支持键盘、MIDI 设备、MIDI 文件模拟和测试用 list 输入</li><li><strong>多种输出方式</strong>：支持控制台打印、实时 MIDI 播放、MIDI 文件录制、WebSocket 推送、JSON 日志、Session 日志和组合输出</li><li><strong>节拍器与 count-in</strong>：支持实时 MIDI click，并可在正式输入和推理前空转若干拍</li><li><strong>分层架构</strong>：清晰的四层结构（Presentation → Application → Domain → Infrastructure），易于扩展</li><li><strong>完整的 Session 日志</strong>：自动记录事件流、推理请求响应、延迟统计、音乐分析和 <code>combined.mid</code></li><li><strong>注入能力</strong>：CLI 支持 <code>--injection-file</code> / <code>--injection-length</code> 预填充 HTTP server 历史</li></ul><hr><h2 id="系统架构概览" tabindex="-1">系统架构概览 <a class="header-anchor" href="#系统架构概览" aria-label="Permalink to &quot;系统架构概览&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────┐</span></span>
<span class="line"><span>│           Presentation (CLI)            │</span></span>
<span class="line"><span>│  uv run streammuse-cli --input-mode ... │</span></span>
<span class="line"><span>└─────────────────┬───────────────────────┘</span></span>
<span class="line"><span>                  │ ApplicationConfig</span></span>
<span class="line"><span>┌─────────────────▼───────────────────────┐</span></span>
<span class="line"><span>│         Application Layer               │</span></span>
<span class="line"><span>│   RealTimeMusicService  (3 threads)     │</span></span>
<span class="line"><span>│   ┌──────────┐ ┌──────┐ ┌───────────┐  │</span></span>
<span class="line"><span>│   │  Input   │ │ Tick │ │ Inference │  │</span></span>
<span class="line"><span>│   │ Worker   │ │ Loop │ │  Worker   │  │</span></span>
<span class="line"><span>│   └──────────┘ └──────┘ └───────────┘  │</span></span>
<span class="line"><span>└──────┬──────────────────────────┬───────┘</span></span>
<span class="line"><span>       │ InputSource / OutputSink │ InferenceEngine</span></span>
<span class="line"><span>┌──────▼──────────────────────────▼───────┐</span></span>
<span class="line"><span>│         Infrastructure Layer            │</span></span>
<span class="line"><span>│  KeyboardInput  →  HttpInferenceClient  │</span></span>
<span class="line"><span>│  MidiDeviceInput → StanleyInferenceEngine│</span></span>
<span class="line"><span>│  Audio/MIDI/JSON/Session/Metronome sinks│</span></span>
<span class="line"><span>└──────────────────────────────────────────┘</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼  HTTP / local model call</span></span>
<span class="line"><span>┌──────────────────┐</span></span>
<span class="line"><span>│  Inference Server│  (fake_inference_server.py / server_lekai.py)</span></span>
<span class="line"><span>└──────────────────┘</span></span></code></pre></div><hr><h2 id="系统要求" tabindex="-1">系统要求 <a class="header-anchor" href="#系统要求" aria-label="Permalink to &quot;系统要求&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>Python</td><td>≥ 3.10</td></tr><tr><td>操作系统</td><td>macOS / Linux</td></tr><tr><td>GPU（可选）</td><td>CUDA / MPS / CPU 取决于模型后端</td></tr><tr><td>MIDI 音频输出（可选）</td><td>python-rtmidi / 系统 MIDI 输出端口</td></tr><tr><td>包管理器</td><td><a href="https://github.com/astral-sh/uv" target="_blank" rel="noreferrer">uv</a></td></tr></tbody></table><hr><h2 id="快速导航" tabindex="-1">快速导航 <a class="header-anchor" href="#快速导航" aria-label="Permalink to &quot;快速导航&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>内容</th></tr></thead><tbody><tr><td><a href="./getting-started/installation.html">安装</a></td><td>环境搭建与依赖安装</td></tr><tr><td><a href="./getting-started/quickstart.html">快速上手</a></td><td>5 分钟运行第一个示例</td></tr><tr><td><a href="./getting-started/configuration.html">配置项</a></td><td>所有 CLI 参数说明</td></tr><tr><td><a href="./architecture/overview.html">架构总览</a></td><td>Clean Architecture 四层设计</td></tr><tr><td><a href="./architecture/domain/overview.html">Domain 层</a></td><td>核心数据模型与 Protocol</td></tr><tr><td><a href="./user-guide/output-types.html">输出类型</a></td><td>7 种用户可选输出类型与 metronome 说明</td></tr><tr><td><a href="./user-guide/session-logging.html">Session 日志</a></td><td>日志文件结构与字段</td></tr><tr><td><a href="./user-guide/music-injection.html">音乐注入</a></td><td>CLI/API 注入历史上下文</td></tr><tr><td><a href="./developer-guide/adding-input-source.html">新增输入源</a></td><td>如何扩展 InputSource</td></tr><tr><td><a href="./developer-guide/adding-output-sink.html">新增输出 Sink</a></td><td>如何扩展 OutputSink</td></tr><tr><td><a href="./developer-guide/adding-inference-engine.html">新增推理引擎</a></td><td>如何扩展 InferenceEngine</td></tr><tr><td><a href="./reference/cli-reference.html">CLI 参考</a></td><td>完整命令行参数表</td></tr></tbody></table>`,14)])])}const m=n(r,[["render",i]]);export{u as __pageData,m as default};
